CREATE VIEW channel_money_sources AS SELECT e.action kind,e.id,e.order_id,e.order_version,e.customer_id,e.store_id,e.amount_cents,e.currency,e.method,e.reference,e.received_at occurred_at,e.created_at recorded_at,e.created_by author_id,CASE WHEN e.action='void' THEN 'void_reference' WHEN v.id IS NOT NULL THEN 'receive_voided' ELSE 'receive_valid' END state,CASE WHEN e.action='receive' THEN e.id ELSE e.source_id END receipt_id,NULL refund_id,CASE WHEN e.action='receive' THEN v.id ELSE e.id END void_id,e.revision source_revision,CASE WHEN e.action='void' THEN 'original_receipt_reference' ELSE 'actual_collection' END actual_date_kind FROM payment_events e LEFT JOIN payment_events v ON v.source_id=e.id AND v.rowid<=coalesce((SELECT max(rowid) FROM payment_events WHERE store_id=e.store_id),0) WHERE e.rowid<=coalesce((SELECT max(rowid) FROM payment_events WHERE store_id=e.store_id),0)
UNION ALL SELECT 'refund',e.id,e.order_id,e.order_version,e.customer_id,e.store_id,e.amount_cents,e.currency,e.method,e.reference,e.refunded_at,e.created_at,e.created_by,'refund_executed',e.receipt_id,e.root_id,NULL,e.revision,'actual_refund' FROM refund_events e WHERE e.action='execute' AND e.rowid<=coalesce((SELECT max(rowid) FROM refund_events WHERE store_id=e.store_id),0);
CREATE TABLE channel_review_roots(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),kind TEXT NOT NULL CHECK(kind IN('receive','void','refund')),source_id TEXT NOT NULL,serial INTEGER NOT NULL CHECK(serial>0),record_number TEXT NOT NULL,first_version_id TEXT NOT NULL UNIQUE REFERENCES channel_review_versions(id) DEFERRABLE INITIALLY DEFERRED,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,record_number),FOREIGN KEY(first_version_id,id) REFERENCES channel_review_versions(id,root_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE channel_review_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES channel_review_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),event_id TEXT NOT NULL UNIQUE REFERENCES channel_review_events(id) DEFERRABLE INITIALLY DEFERRED,payment_prefix INTEGER NOT NULL CHECK(payment_prefix>=0),refund_prefix INTEGER NOT NULL CHECK(refund_prefix>=0),source_snapshot_json TEXT NOT NULL CHECK(json_valid(source_snapshot_json)),title TEXT NOT NULL,data_json TEXT NOT NULL CHECK(json_valid(data_json)),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,version),UNIQUE(id,root_id),FOREIGN KEY(event_id,id) REFERENCES channel_review_events(id,version_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE channel_review_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES channel_review_roots(id),version_id TEXT NOT NULL REFERENCES channel_review_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('record','withdraw')),status TEXT NOT NULL CHECK(status IN('recorded','withdrawn')),reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),UNIQUE(id,version_id));
CREATE VIEW channel_review_current AS SELECT * FROM channel_review_events e WHERE revision=(SELECT max(revision) FROM channel_review_events WHERE root_id=e.root_id);
CREATE TRIGGER channel_review_root_source BEFORE INSERT ON channel_review_roots BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM channel_money_sources m WHERE m.kind=NEW.kind AND m.id=NEW.source_id AND m.store_id=NEW.store_id AND m.recorded_at<=NEW.created_at) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM channel_review_roots WHERE store_id=NEW.store_id),1) OR NEW.record_number IS NOT 'CR-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'channel fixed actual money source/store/number') END;END;
CREATE TRIGGER channel_review_version_source BEFORE INSERT ON channel_review_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM channel_review_roots r JOIN channel_money_sources m ON m.kind=r.kind AND m.id=r.source_id AND m.store_id=r.store_id WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND m.recorded_at<=NEW.created_at AND NEW.source_snapshot_json=json_object('kind',m.kind,'id',m.id,'order_id',m.order_id,'order_version',m.order_version,'customer_id',m.customer_id,'store_id',m.store_id,'amount_cents',m.amount_cents,'currency',m.currency,'method',m.method,'reference',m.reference,'occurred_at',m.occurred_at,'recorded_at',m.recorded_at,'author_id',m.author_id,'state',m.state,'receipt_id',m.receipt_id,'refund_id',m.refund_id,'void_id',m.void_id,'source_revision',m.source_revision,'actual_date_kind',m.actual_date_kind)) OR NEW.payment_prefix<>coalesce((SELECT max(rowid) FROM payment_events WHERE store_id=NEW.store_id),0) OR NEW.refund_prefix<>coalesce((SELECT max(rowid) FROM refund_events WHERE store_id=NEW.store_id),0) OR EXISTS(SELECT 1 FROM payment_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM refund_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR NEW.version<>coalesce((SELECT max(version)+1 FROM channel_review_versions WHERE root_id=NEW.root_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM channel_review_events WHERE store_id=NEW.store_id),0) OR NEW.version=1 AND NOT EXISTS(SELECT 1 FROM channel_review_roots r WHERE r.id=NEW.root_id AND r.first_version_id=NEW.id AND r.created_at=NEW.created_at AND r.created_by=NEW.created_by) THEN RAISE(ABORT,'channel fixed captured current source/version pairing') END;END;
CREATE TRIGGER channel_review_event_source BEFORE INSERT ON channel_review_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM channel_review_versions v WHERE v.id=NEW.version_id AND v.root_id=NEW.root_id AND v.store_id=NEW.store_id) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM channel_review_events WHERE store_id=NEW.store_id),1) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM channel_review_events WHERE root_id=NEW.root_id),1) OR NEW.action='record' AND (NEW.status<>'recorded' OR NOT EXISTS(SELECT 1 FROM channel_review_versions v WHERE v.id=NEW.version_id AND v.event_id=NEW.id AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by AND v.reason=NEW.reason AND v.version=coalesce((SELECT max(v2.version)+1 FROM channel_review_events e JOIN channel_review_versions v2 ON v2.id=e.version_id WHERE e.root_id=NEW.root_id),1))) THEN RAISE(ABORT,'channel continuous paired event') END;
SELECT CASE WHEN NEW.action='withdraw' AND (NEW.status<>'withdrawn' OR NOT EXISTS(SELECT 1 FROM channel_review_current e WHERE e.root_id=NEW.root_id AND e.status='recorded' AND e.version_id=NEW.version_id)) THEN RAISE(ABORT,'channel explicit current withdrawal') END;END;
CREATE TRIGGER channel_review_typed_data BEFORE INSERT ON channel_review_versions WHEN NOT (NEW.data_json=json_object('channel_label',json_extract(NEW.data_json,'$.channel_label'),'reference_status',json_extract(NEW.data_json,'$.reference_status'),'reference',json_extract(NEW.data_json,'$.reference'),'evidence_date_status',json_extract(NEW.data_json,'$.evidence_date_status'),'evidence_date',json_extract(NEW.data_json,'$.evidence_date'),'observed_status',json_extract(NEW.data_json,'$.observed_status'),'observed_amount_cents',json_extract(NEW.data_json,'$.observed_amount_cents'),'conclusion',json_extract(NEW.data_json,'$.conclusion'),'source_note',json_extract(NEW.data_json,'$.source_note'),'review_note',json_extract(NEW.data_json,'$.review_note')) AND (json_type(NEW.data_json,'$.channel_label') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.channel_label'))) BETWEEN 1 AND 300 AND length(json_extract(NEW.data_json,'$.channel_label'))<=300 AND instr(json_extract(NEW.data_json,'$.channel_label'),char(0))=0) AND (json_type(NEW.data_json,'$.source_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.source_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.source_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.source_note'),char(0))=0) AND (json_type(NEW.data_json,'$.review_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.review_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.review_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.review_note'),char(0))=0) AND (json_extract(NEW.data_json,'$.reference_status')='unknown' AND json_type(NEW.data_json,'$.reference')='null' OR json_extract(NEW.data_json,'$.reference_status')='recorded' AND ((json_type(NEW.data_json,'$.reference') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.reference'))) BETWEEN 1 AND 1000 AND length(json_extract(NEW.data_json,'$.reference'))<=1000 AND instr(json_extract(NEW.data_json,'$.reference'),char(0))=0))) AND (json_extract(NEW.data_json,'$.evidence_date_status')='unknown' AND json_type(NEW.data_json,'$.evidence_date')='null' OR json_extract(NEW.data_json,'$.evidence_date_status')='recorded' AND (length(json_extract(NEW.data_json,'$.evidence_date'))=10 AND date(json_extract(NEW.data_json,'$.evidence_date'),'+0 days') IS json_extract(NEW.data_json,'$.evidence_date') AND json_extract(NEW.data_json,'$.evidence_date')<=substr(NEW.created_at,1,10))) AND (json_extract(NEW.data_json,'$.observed_status')='unknown' AND json_type(NEW.data_json,'$.observed_amount_cents')='null' OR json_extract(NEW.data_json,'$.observed_status')='recorded' AND (json_type(NEW.data_json,'$.observed_amount_cents') IS 'integer' AND json_extract(NEW.data_json,'$.observed_amount_cents') BETWEEN 0 AND 1000000000000)) AND json_type(NEW.data_json,'$.reference_status') IS 'text' AND json_type(NEW.data_json,'$.evidence_date_status') IS 'text' AND json_type(NEW.data_json,'$.observed_status') IS 'text' AND json_type(NEW.data_json,'$.conclusion') IS 'text' AND (json_extract(NEW.data_json,'$.conclusion')='unknown' OR json_extract(NEW.data_json,'$.observed_status')='recorded' AND (json_extract(NEW.data_json,'$.conclusion')='consistent' AND json_extract(NEW.data_json,'$.observed_amount_cents')=json_extract(NEW.source_snapshot_json,'$.amount_cents') OR json_extract(NEW.data_json,'$.conclusion')='difference' AND json_extract(NEW.data_json,'$.observed_amount_cents')<>json_extract(NEW.source_snapshot_json,'$.amount_cents')))) BEGIN SELECT RAISE(ABORT,'channel explicit canonical evidence and manual conclusion');END;
CREATE TRIGGER channel_review_roots_actor BEFORE INSERT ON channel_review_roots WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM channel_review_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'channel current actor/time');END;
CREATE TRIGGER channel_review_roots_no_update BEFORE UPDATE ON channel_review_roots BEGIN SELECT RAISE(ABORT,'channel immutable');END;
CREATE TRIGGER channel_review_roots_no_delete BEFORE DELETE ON channel_review_roots BEGIN SELECT RAISE(ABORT,'channel immutable');END;
CREATE TRIGGER channel_review_versions_actor BEFORE INSERT ON channel_review_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM channel_review_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'channel current actor/time');END;
CREATE TRIGGER channel_review_versions_no_update BEFORE UPDATE ON channel_review_versions BEGIN SELECT RAISE(ABORT,'channel immutable');END;
CREATE TRIGGER channel_review_versions_no_delete BEFORE DELETE ON channel_review_versions BEGIN SELECT RAISE(ABORT,'channel immutable');END;
CREATE TRIGGER channel_review_versions_text BEFORE INSERT ON channel_review_versions WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.title)) NOT BETWEEN 1 AND 160 OR length(NEW.title)>160 OR instr(NEW.title,char(0))>0 BEGIN SELECT RAISE(ABORT,'channel explicit text');END;
CREATE TRIGGER channel_review_events_actor BEFORE INSERT ON channel_review_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM channel_review_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'channel current actor/time');END;
CREATE TRIGGER channel_review_events_no_update BEFORE UPDATE ON channel_review_events BEGIN SELECT RAISE(ABORT,'channel immutable');END;
CREATE TRIGGER channel_review_events_no_delete BEFORE DELETE ON channel_review_events BEGIN SELECT RAISE(ABORT,'channel immutable');END;
CREATE TRIGGER channel_review_events_text BEFORE INSERT ON channel_review_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000 OR instr(NEW.next_step,char(0))>0 BEGIN SELECT RAISE(ABORT,'channel explicit text');END;
